// DecodeError identifies and decodes a declared custom error.
func (c *IDiesisNameVerifierBinding) DecodeError(raw []byte) (any, error) {
	if len(raw) < 4 {
		return nil, fmt.Errorf("revert payload is shorter than a selector")
	}
	if definition, err := c.customError("AttestationAlreadySubmitted()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeAttestationAlreadySubmittedError(raw)
	}
	if definition, err := c.customError("BadSignature()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeBadSignatureError(raw)
	}
	if definition, err := c.customError("NotIssuer()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeNotIssuerError(raw)
	}
	if definition, err := c.customError("UnknownAttestation()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeUnknownAttestationError(raw)
	}
	return nil, fmt.Errorf("unknown custom error selector %x", raw[:4])
}
